INSERT INTO `exercises` VALUES (3,36,'QUIZ','Kiểm tra kiến thức React','',NULL,100,NULL,'123232',NULL,'React','5','MEDIUM','[{\"orderIndex\":0,\"questionText\":\"Hook nào được dùng để quản lý state trong React functional component?\",\"optionA\":\"useEffect\",\"optionB\":\"useState\",\"optionC\":\"useRef\",\"optionD\":\"useContext\",\"correctAnswer\":\"B\",\"explanation\":\"useState là hook cơ bản nhất để khai báo và cập nhật state trong functional component. Mỗi lần state thay đổi, component sẽ re-render lại.\"},{\"orderIndex\":1,\"questionText\":\"useEffect(() => { ... }, []) với dependency array rỗng sẽ chạy khi nào?\",\"optionA\":\"Mỗi lần component re-render\",\"optionB\":\"Chỉ khi dependency thay đổi\",\"optionC\":\"Chỉ một lần sau lần render đầu tiên \",\"optionD\":\"Không bao giờ chạy\",\"correctAnswer\":\"C\",\"explanation\":\"Dependency array rỗng [] có nghĩa là effect không phụ thuộc vào bất kỳ giá trị nào, nên chỉ chạy đúng một lần sau khi component mount — tương đương componentDidMount trong class component.\"},{\"orderIndex\":2,\"questionText\":\"Trong React, \\\"props\\\" là gì?\",\"optionA\":\"Dữ liệu nội bộ của component, chỉ component đó quản lý\",\"optionB\":\"dữ liệu được truyền từ component cha xuống component con\",\"optionC\":\" Một hook dùng để fetch dữ liệu từ API\",\"optionD\":\"Trạng thái global dùng chung toàn ứng dụng\",\"correctAnswer\":\"B\",\"explanation\":\" Props (properties) là cơ chế truyền dữ liệu một chiều từ parent xuống child component. Props là read-only — component con không được phép tự thay đổi props nhận được.\"}]',NULL,'STANDARD',NULL),(4,38,'QUIZ','Bai tạm','Làm vui',NULL,100,NULL,NULL,NULL,'Opp','','MEDIUM','[{\"orderIndex\":0,\"questionText\":\"Css là gì\",\"optionA\":\"là vui\",\"optionB\":\"là hay\",\"optionC\":\"là lá la\",\"optionD\":\"là ngôn ngữ lập trình\",\"correctAnswer\":\"D\",\"explanation\":\"Chọn A\"},{\"orderIndex\":1,\"questionText\":\"Hỏi chơi chơi\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"dễ mà\"},{\"orderIndex\":2,\"questionText\":\"Chọn A\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"Chọn A\"},{\"orderIndex\":3,\"questionText\":\"Chọn A\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"Chọn A\"},{\"orderIndex\":4,\"questionText\":\"Chọn A\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"Chọn A\"},{\"orderIndex\":5,\"questionText\":\"Chọn A\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"Chọn A\"},{\"orderIndex\":6,\"questionText\":\"Chọn A\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"Chọn A\"},{\"orderIndex\":7,\"questionText\":\"Chọn A\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"Chọn A\"},{\"orderIndex\":8,\"questionText\":\"Chọn A\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"Chọn A\"},{\"orderIndex\":9,\"questionText\":\"Hỏi vui mà\",\"optionA\":\"Chọn A\",\"optionB\":\"Chọn A\",\"optionC\":\"Chọn A\",\"optionD\":\"Chọn A\",\"correctAnswer\":\"A\",\"explanation\":\"Chọn A\"}]',NULL,'STANDARD',NULL),(5,44,'CODE','Tính tổng các số chẵn','Viết hàm sumEven(arr) nhận vào một mảng số nguyên, trả về tổng các số chẵn trong mảng. Nếu không có số chẵn, trả về 0.','javascript',100,'index.js','[\"1. Hàm phải xử lý mảng rỗng, trả về 0\",\"2. Chỉ cộng các số chẵn (chia hết cho 2)\",\"3. Số âm chẵn vẫn được tính\"]','function sumEven(arr) {\n  // Viết code của bạn ở đây\n}\n\nconst input = require(\'fs\').readFileSync(\'/dev/stdin\',\'utf8\').trim();\nconst arr = input.split(\' \').map(Number);\nconsole.log(sumEven(arr));','Array','15','EASY',NULL,'[{\"label\":null,\"input\":\"1 2 3 4 5 6\",\"expectedOutput\":\"12\",\"hidden\":false},{\"label\":null,\"input\":\"1 3 5 7\",\"expectedOutput\":\"0\",\"hidden\":false},{\"label\":null,\"input\":\"\",\"expectedOutput\":\"0\",\"hidden\":false},{\"label\":null,\"input\":\"-2 -4 3\",\"expectedOutput\":\"-6\",\"hidden\":false}]','STANDARD',NULL),(6,64,'QUIZ','bài tập','Làm vui',NULL,100,NULL,NULL,NULL,'OOP','10','EASY','[{\"orderIndex\":0,\"questionText\":\"Điền vào chỗ trống: \\\"Cá không ăn ... cá ươn\\\"\",\"optionA\":\"muối\",\"optionB\":\"mắm tôm\",\"optionC\":\"mắm rò\",\"optionD\":\"cơm\",\"correctAnswer\":\"A\",\"explanation\":\"vì đúng\"}]',NULL,'STANDARD',NULL),(7,65,'CODE','Tính tổng các phần tử trong mảng','Viết hàm tính tổng tất cả các phần tử trong một mảng số nguyên.\nVí dụ: [1, 2, 3, 4, 5] → 15\nVí dụ: [] →','java',100,'Main.java','[\"Hàm phải xử lý mảng rỗng, trả về 0\",\"Hàm phải xử lý số âm\",\"Không dùng thư viện ngoài\"]','import java.util.Scanner;\n\npublic class Main {\n    public static int sumArray(int[] arr) {\n        // Viết code của bạn ở đây\n        return 0;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.isEmpty()) {\n            System.out.println(0);\n            return;\n        }\n        String[] parts = line.split(\" \");\n        int[] arr = new int[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            arr[i] = Integer.parseInt(parts[i]);\n        }\n        System.out.println(sumArray(arr));\n    }\n}','Array, Loop, Java','','EASY',NULL,'[{\"label\":null,\"input\":\"1 2 3 4 5\",\"expectedOutput\":\"15\",\"hidden\":false},{\"label\":null,\"input\":\"\",\"expectedOutput\":\"0\",\"hidden\":false},{\"label\":null,\"input\":\"-1 -2 3\",\"expectedOutput\":\"0\",\"hidden\":false}]','STANDARD',NULL),(8,79,'CODE','Thiết kế class BankAccount','Viết class BankAccount với các yêu cầu sau:\n- Thuộc tính private: balance (double), owner (String)\n- Constructor: BankAccount(String owner, double initialBalance)\n- deposit(double amount): cộng tiền, bỏ qua nếu amount <= 0\n- withdraw(double amount): trừ tiền, bỏ qua nếu amount <= 0 hoặc vượt số dư\n- getBalance(): trả về số dư hiện tại\n- getOwner(): trả về tên chủ tài khoản','java',100,'Main.java','[\" Thuộc tính balance và owner phải là private\",\" deposit bỏ qua số tiền âm hoặc bằng 0\",\"withdraw không cho rút quá số dư\",\" getBalance và getOwner trả về đúng giá trị\"]','public class BankAccount {\n    // Khai báo thuộc tính ở đây\n\n    public BankAccount(String owner, double initialBalance) {\n        // Viết code ở đây\n    }\n\n    public void deposit(double amount) {\n        // Viết code ở đây\n    }\n\n    public void withdraw(double amount) {\n        // Viết code ở đây\n    }\n\n    public double getBalance() {\n        // Viết code ở đây\n        return 0;\n    }\n\n    public String getOwner() {\n        // Viết code ở đây\n        return \"\";\n    }\n}','OOP, Java','20 phút','MEDIUM',NULL,'[]','UNIT_TEST','public class Main {\n    static int passed = 0;\n    static int total = 0;\n\n    static void test(String name, boolean condition) {\n        total++;\n        if (condition) { passed++; System.out.println(\"PASS: \" + name); }\n        else           { System.out.println(\"FAIL: \" + name); }\n    }\n\n    public static void main(String[] args) {\n        BankAccount acc = new BankAccount(\"Alice\", 1000);\n\n        test(\"Initial balance\",      acc.getBalance() == 1000);\n        test(\"Owner name\",           acc.getOwner().equals(\"Alice\"));\n\n        acc.deposit(500);\n        test(\"Deposit valid\",        acc.getBalance() == 1500);\n\n        acc.deposit(-100);\n        test(\"Deposit negative skip\",acc.getBalance() == 1500);\n\n        acc.withdraw(200);\n        test(\"Withdraw valid\",       acc.getBalance() == 1300);\n\n        acc.withdraw(9999);\n        test(\"Overdraft rejected\",   acc.getBalance() == 1300);\n\n        System.out.println(\"RESULT: \" + passed + \"/\" + total);\n    }\n}'),(9,106,'QUIZ','Kiểu dữ liệu trong C++','Kiểm tra hiểu biết về các kiểu dữ liệu C++',NULL,100,NULL,NULL,NULL,'kiểu dữ liệu, biến','5 phút','EASY','[{\"orderIndex\":0,\"questionText\":\"Kiểu dữ liệu nào dùng để lưu số thực trong C++?\",\"optionA\":\"int\",\"optionB\":\"char\",\"optionC\":\"double\",\"optionD\":\"bool\",\"correctAnswer\":\"C\",\"explanation\":\"double lưu số thực (có phần thập phân), int chỉ lưu số nguyên.\"},{\"orderIndex\":1,\"questionText\":\"Kết quả của 7 / 2 trong C++ (kiểu int) là bao nhiêu?\",\"optionA\":\"3.5\",\"optionB\":\"3\",\"optionC\":\"4\",\"optionD\":\"3.0\",\"correctAnswer\":\"B\",\"explanation\":\" Phép chia 2 số int trong C++ trả về int, phần thập phân bị cắt bỏ → 7/2 = 3.\"}]',NULL,NULL,NULL),(10,108,'QUIZ','Exercise title: Kiểm tra kiến thức cơ bản C++','Kiểm tra hiểu biết cơ bản về ngôn ngữ C++',NULL,100,NULL,NULL,NULL,'C++ basics','5 phút','EASY','[{\"orderIndex\":0,\"questionText\":\"C++ là ngôn ngữ lập trình thuộc loại \",\"optionA\":\"Ngôn ngữ thông dịch (interpreted)\",\"optionB\":\"Ngôn ngữ biên dịch (compiled)\",\"optionC\":\"Ngôn ngữ script\",\"optionD\":\"Ngôn ngữ markup\",\"correctAnswer\":\"B\",\"explanation\":\"C++ là ngôn ngữ biên dịch, code được compile thành file thực thi trước khi chạy.\"},{\"orderIndex\":1,\"questionText\":\"Để in ra màn hình trong C++, ta dùng lệnh nào?\",\"optionA\":\"print()\",\"optionB\":\"System.out.println()\",\"optionC\":\"cout << \",\"optionD\":\"printf() only\",\"correctAnswer\":\"C\",\"explanation\":\" C++ dùng cout << để xuất dữ liệu ra màn hình, thuộc thư viện <iostream>.\"},{\"orderIndex\":2,\"questionText\":\"Dòng nào cần có trong mọi chương trình C++?\",\"optionA\":\"#include <stdio>\",\"optionB\":\"#include <iostream>\",\"optionC\":\"import iostream\",\"optionD\":\"using iostream\",\"correctAnswer\":\"B\",\"explanation\":\"#include <iostream> để dùng cout và cin.\"}]',NULL,NULL,NULL),(11,109,'CODE','Hello World C++','Viết chương trình C++ đầu tiên in ra màn hình','cpp',100,'main.cpp','[\" In ra đúng dòng chữ \\\"Xin chao, toi hoc C++!\\\"\"]','#include <iostream>\nusing namespace std;\n\nint main() {\n    // Viết code của bạn ở đây\n    \n    return 0;\n}','C++ cơ bản, iostream','10 phút','EASY',NULL,'[{\"label\":null,\"input\":\"\",\"expectedOutput\":\"Xin chao, toi hoc C++!\",\"hidden\":false}]','STANDARD',NULL),(12,110,'CODE','Tính diện tích hình chữ nhật','Nhập chiều dài và chiều rộng, tính và in diện tích','cpp',100,'main.cpp','[\"Nhập 2 số nguyên từ stdin (chiều dài, chiều rộng)\",\"In ra diện tích = dài * rộng\"]','#include <iostream>\nusing namespace std;\n\nint main() {\n    int dai, rong;\n    // Nhập chiều dài và chiều rộng\n    \n    // Tính và in diện tích\n    \n    return 0;\n}','biến, nhập xuất, kiểu dữ liệu','15 phút','EASY',NULL,'[{\"label\":null,\"input\":\"5 3\",\"expectedOutput\":\"15\",\"hidden\":false},{\"label\":null,\"input\":\"10 4\",\"expectedOutput\":\"40\",\"hidden\":false}]','STANDARD',NULL),(13,107,'CODE','Đổi nhiệt độ Celsius sang Fahrenheit','Nhập nhiệt độ Celsius, chuyển sang Fahrenheit','cpp',100,'main.cpp','[\"Nhập số thực celsius từ stdin\",\"In ra fahrenheit theo công thức F = C * 9.0 / 5 + 32\"]','#include <iostream>\nusing namespace std;\n\nint main() {\n    double celsius;\n    // Nhập celsius\n    \n    // Công thức: F = C * 9 / 5 + 32\n    \n    return 0;\n}','kiểu dữ liệu, toán tử, ép kiểu','15 phút','EASY',NULL,'[{\"label\":null,\"input\":\"0\",\"expectedOutput\":\"32\",\"hidden\":false},{\"label\":null,\"input\":\"100\",\"expectedOutput\":\"212\",\"hidden\":false}]','STANDARD',NULL),(14,111,'CODE','Số chẵn hay số lẻ','Nhập một số nguyên, kiểm tra chẵn hay lẻ','cpp',100,'main.cpp','[\"Nhập số nguyên n từ stdin\",\"In \\\"Chan\\\" nếu n chia hết cho 2\",\"In \\\"Le\\\" nếu n không chia hết cho 2\"]','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    // Nhập n\n    \n    // Kiểm tra chẵn lẻ bằng toán tử %\n    \n    return 0;\n}','toán tử, điều kiện, toán tử %','15 phút','EASY',NULL,'[{\"label\":null,\"input\":\"4 \",\"expectedOutput\":\"Chan\",\"hidden\":false},{\"label\":null,\"input\":\"7\",\"expectedOutput\":\"Le\",\"hidden\":false},{\"label\":null,\"input\":\"0\",\"expectedOutput\":\"Chan\",\"hidden\":false}]','STANDARD',NULL),(15,118,'CODE','Tính tổng hai số nguyên','Viết hàm sum(a, b) trả về tổng của hai số nguyên a và b.','cpp',100,'main.cpp','[\"Hàm sum(a, b) phải trả về tổng của a và b\"]','#include <iostream>\nusing namespace std;\n\nint sum(int a, int b) {\n    // Viết code của bạn ở đây\n    return 0;\n}\n\nint main() {\n    return 0;\n}','C++','15 phút','EASY',NULL,'[]','UNIT_TEST','#include <cassert>\n#include <iostream>\nusing namespace std;\n\nint sum(int a, int b);\n\nint main() {\n    assert(sum(1, 2) == 3);\n    assert(sum(0, 0) == 0);\n    assert(sum(-1, 1) == 0);\n    assert(sum(100, 200) == 300);\n    cout << \"ALL_TESTS_PASSED\" << endl;\n    return 0;\n}'),(16,119,'CODE','Tính tổng hai số nguyên','Viết hàm sum(a, b) trả về tổng của hai số nguyên a và b.','cpp',100,'main.cpp','[\"Hàm sum(a, b) phải trả về tổng của a và b\"]','#include <iostream>\nusing namespace std;\n\nint sum(int a, int b) {\n    // Viết code của bạn ở đây\n    return 0;\n}\n\nint main() {\n    return 0;\n}','C++ Basics','15','EASY',NULL,'[]','UNIT_TEST','#include <cassert>\n#include <iostream>\nusing namespace std;\n\nint sum(int a, int b);\n\nint main() {\n    assert(sum(1, 2) == 3);\n    assert(sum(0, 0) == 0);\n    assert(sum(-1, 1) == 0);\n    assert(sum(100, 200) == 300);\n    cout << \"ALL_TESTS_PASSED\" << endl;\n    return 0;\n}'),(17,120,'CODE','Kiểm tra số chẵn lẻ','Viết hàm isEven(n) trả về true nếu n là số chẵn, false nếu là số lẻ.','java',100,'Main.java','[]','public class Solution {\n    public static boolean isEven(int n) {\n        // Viết code của bạn ở đây\n        return false;\n    }\n}','Java Basics','10 phút','EASY',NULL,'[]','UNIT_TEST','public class Main {\n    public static void main(String[] args) {\n        if (Solution.isEven(2)  != true)  { System.out.println(\"FAIL: isEven(2) phải là true\");  return; }\n        if (Solution.isEven(3)  != false) { System.out.println(\"FAIL: isEven(3) phải là false\"); return; }\n        if (Solution.isEven(0)  != true)  { System.out.println(\"FAIL: isEven(0) phải là true\");  return; }\n        if (Solution.isEven(-4) != true)  { System.out.println(\"FAIL: isEven(-4) phải là true\"); return; }\n        if (Solution.isEven(-7) != false) { System.out.println(\"FAIL: isEven(-7) phải là false\");return; }\n        System.out.println(\"ALL_TESTS_PASSED\");\n    }\n}'),(18,124,'CODE','Bài mẫu','','java',100,'Main.java','[]','','','','EASY',NULL,'[]','STANDARD',NULL),(19,136,'CODE','Tính tổng các số trong danh sách','Viết hàm `sum_list(nums)` nhận vào một danh sách số nguyên và trả về tổng các phần tử. Nếu danh sách rỗng, trả về 0. |','python',100,'main.py','[\" Hàm phải xử lý được danh sách rỗng → trả về 0 \",\"Hàm phải tính đúng tổng với số dương\",\"Hàm phải tính đúng tổng với số âm \",\"Hàm phải xử lý đúng danh sách có 1 phần tử\"]','def sum_list(nums):\n    # Viết code của bạn ở đây\n    pass\n','Python Basics','10 phút','EASY',NULL,'[]','UNIT_TEST','\ndef main():\n    if sum_list([]) != 0:\n        print(\"FAIL: sum_list([]) phải là 0\"); return\n    if sum_list([1, 2, 3]) != 6:\n        print(\"FAIL: sum_list([1, 2, 3]) phải là 6\"); return\n    if sum_list([-1, -2, -3]) != -6:\n        print(\"FAIL: sum_list([-1, -2, -3]) phải là -6\"); return\n    if sum_list([5]) != 5:\n        print(\"FAIL: sum_list([5]) phải là 5\"); return\n    if sum_list([10, -3, 7]) != 14:\n        print(\"FAIL: sum_list([10, -3, 7]) phải là 14\"); return\n    print(\"ALL_TESTS_PASSED\")\n\nmain()\n'),(20,137,'CODE','Tính tổng các số trong danh sách','Dòng đầu tiên là số nguyên n (số lượng phần tử). Dòng thứ hai là n số nguyên cách nhau bởi dấu cách. In ra tổng của các số đó.','python',100,'main.py','[]','# Đọc input và in kết quả\nn = int(input())\nnums = list(map(int, input().split()))\n\n# Viết code của bạn ở đây','Python Basics','10 phút','EASY',NULL,'[{\"label\":null,\"input\":\"3\\n1 2 3\",\"expectedOutput\":\"6\",\"hidden\":false},{\"label\":null,\"input\":\"5\\n10 -3 7 0 -4\",\"expectedOutput\":\"10\",\"hidden\":false},{\"label\":null,\"input\":\"1\\n5\",\"expectedOutput\":\"5\",\"hidden\":false},{\"label\":null,\"input\":\"3\\n-1 -2 -3\",\"expectedOutput\":\"-6\",\"hidden\":false}]','STANDARD',NULL),(21,143,'CODE','Đếm số chẵn trong mảng','Dòng đầu tiên là số nguyên `n` (số lượng phần tử). Dòng thứ hai là `n` số nguyên cách nhau bởi dấu cách. In ra số lượng số chẵn trong mảng đó.','java',100,'Main.java','[]','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n\n        // Viết code của bạn ở đây\n    }\n}','Java Basics','10 phút','EASY',NULL,'[{\"label\":null,\"input\":\"5\\n1 2 3 4 5\",\"expectedOutput\":\"2\",\"hidden\":false},{\"label\":null,\"input\":\"4\\n2 4 6 8\",\"expectedOutput\":\"4\",\"hidden\":false},{\"label\":null,\"input\":\"3\\n1 3 5\",\"expectedOutput\":\"0\",\"hidden\":false},{\"label\":null,\"input\":\"6\\n-2 0 3 -5 8 7\",\"expectedOutput\":\"3\",\"hidden\":false}]','STANDARD',NULL),(22,144,'CODE','Tính giai thừa','Viết hàm `factorial(int n)` trả về giai thừa của `n`. Biết rằng `0! = 1`, `1! = 1`, `n! = n * (n-1) * ... * 1`.','java',100,'Main.java','[\" `factorial(0)` phải trả về `1`\",\"`factorial(1)` phải trả về `1`\",\" Tính đúng với số dương\",\"Tính đúng với số lớn (dùng `long` thay vì `int`)\"]','public class Solution {\n    public static long factorial(int n) {\n        // Viết code của bạn ở đây\n        return 0;\n    }\n}','Java Basics','10 phút','EASY',NULL,'[]','UNIT_TEST','public class Main {\n    public static void main(String[] args) {\n        if (Solution.factorial(0) != 1)\n            { System.out.println(\"FAIL: factorial(0) phải là 1\"); return; }\n        if (Solution.factorial(1) != 1)\n            { System.out.println(\"FAIL: factorial(1) phải là 1\"); return; }\n        if (Solution.factorial(5) != 120)\n            { System.out.println(\"FAIL: factorial(5) phải là 120\"); return; }\n        if (Solution.factorial(10) != 3628800)\n            { System.out.println(\"FAIL: factorial(10) phải là 3628800\"); return; }\n        if (Solution.factorial(12) != 479001600L)\n            { System.out.println(\"FAIL: factorial(12) phải là 479001600\"); return; }\n\n        System.out.println(\"ALL_TESTS_PASSED\");\n    }\n}');
