INSERT INTO `lessons` VALUES (2,2,'VIDEO','Bài 1: Cấu trúc thư mục chuẩn trong Spring Boot',NULL,600,'Dưới đây là nội dung tóm tắt về cấu trúc thư mục chuẩn trong Spring Boot:\n* Thư mục `src/main/java`: chứa mã nguồn Java chính của dự án.\n* Thư mục `src/main/resources`: chứa các tài nguyên như file cấu hình, file ngôn ngữ, v.v.\n* Thư mục `src/test/java`: chứa mã nguồn Java dùng для kiểm thử dự án.\n* Thư mục `target`: chứa các file binary được biên dịch từ mã nguồn Java.',1,'https://youtube.com/watch?v=12345abcde','2026-05-06 04:09:41.355886',1,NULL,NULL,NULL),(9,2,'VIDEO','Bài 1: Cấu trúc dự án Spring Boot',NULL,600,NULL,1,NULL,'2026-05-09 19:52:51.000000',0,NULL,NULL,NULL),(17,3,'VIDEO','Bài 1: ReactJS là gì ? Tại sao nên học ReactJS ?','https://www.youtube.com/watch?v=x0fSBAgBrOQ&list=PL_-VfJajZj0UXjlKfBwFX73usByw3Ph9Q&index=1',641,'Bài học \"ReactJS là gì ? Tại sao nên học ReactJS ?\" có nội dung chính như sau:\n\n* ReactJS là một thư viện được viết bởi Facebook, dùng để xây dựng giao diện người dùng. Nó là một dự án mã nguồn mở và được nhiều người sử dụng.\n* Có nhiều lý do nên học ReactJS, bao gồm:\n + ReactJS là một trong những thư viện được sử dụng nhiều nhất trong lĩnh vực phát triển web.\n + Nó có một cộng đồng lớn và được nhiều công ty lớn sử dụng, bao gồm Facebook, Instagram, và nhiều hơn nữa.\n + ReactJS được đánh giá là thân thiện với SEO và có thể giúp cải thiện thứ hạng của trang web trên các công cụ tìm kiếm.\n* Việc học ReactJS có thể mang lại nhiều lợi ích, bao gồm tăng cơ hội việc làm và khả năng phát triển các ứng dụng web phức tạp.',3,NULL,NULL,0,'[00:00:00] Anh\n[00:00:04] ở sách giáo khoa không trả lời w8 cho\n[00:00:06] quá các chị em trong cái này chúng ta sẽ\n[00:00:09] cùng tìm hiểu xem ra check là gì và\n[00:00:11] những lý do nào và khi chúng ta nên học\n[00:00:14] cái chén ở đầu tiên thì các bạn cần nắm\n[00:00:16] được nữa chat Nó là một thư viện được\n[00:00:18] viết nên bởi cho scape thế nên là các\n[00:00:20] bạn cần phải có cái