INSERT INTO `submissions` VALUES ('0389e9a0-dd48-46f4-a5b9-8b323f579e74',10,'b645fee7-81d2-4d42-9b88-672f1aa828e8','{\"code\":null,\"answers\":{\"0\":\"B\",\"1\":\"C\",\"2\":\"B\"}}',100,'Học viên đã trả lời đúng tất cả các câu hỏi, thể hiện kiến thức tốt về ngôn ngữ lập trình C++.','2026-05-31 02:13:05','PASSED',2),('060602d8-4852-42ad-b55b-44f54a21d0b5',8,'6b54c110-f8c9-4051-994c-c45629db02f5','{\"code\":\"public class BankAccount {\\n    private double balance;\\n    private String owner;\\n\\n    public BankAccount(String owner, double initialBalance) {\\n        this.owner = owner;\\n        this.balance = initialBalance;\\n    }\\n\\n    public void deposit(double amount) {\\n        balance += amount; // không check âm\\n    }\\n\\n    public void withdraw(double amount) {\\n        if (amount <= 0) return;\\n        if (amount > balance) return;\\n        balance -= amount;\\n    }\\n\\n    public double getBalance() { return balance; }\\n    public String getOwner()   { return owner; }\\n}\",\"answers\":null}',0,'Code bạn cung cấp đang thiếu phương thức `main` để chạy Unit Test. Để chạy Unit Test, bạn cần tạo một phương thức `main` trong class khác (ví dụ `Main`) để gọi các phương thức test.\n\nVí dụ, bạn có thể thêm một thử nghiệm đơn giản như sau:\n\n```java\npublic class Main {\n    public static void main(String[] args) {\n        // Tạo một tài khoản ngân hàng mới với 1000 VND\n        BankAccount account = new BankAccount(\"Nguyen Van A\", 1000);\n\n        // Nạp tiền vào tài khoản\n        account.deposit(500);\n\n        // Xuống tiền từ tài khoản\n        account.withdraw(200);\n\n        // In trạng thái hiện tại của tài khoản\n        System.out.println(\"Tài khoản: \" + account.getOwner());\n        System.out.println(\"Số dư hiện tại: \" + account.getBalance());\n    }\n}\n```\n\nVề phần thực thi các phương thức `deposit` và `withdraw`, bạn cần kiểm tra xem giá trị nạp/xuống có hợp lệ không. Ví dụ, bạn có thể thêm mã kiểm tra để ngăn chặn việc nạp/xuống tiền âm.','2026-05-27 20:27:12','SUBMITTED',1),('06be9b1c-0b77-41ad-b9fb-9dcc6ac62635',3,'2d2059b1-3e6b-4d40-b7c8-c798fbe27186','{\"code\":null,\"answers\":{\"0\":\"B\",\"1\":\"A\",\"2\":\"B\"}}',67,'Học viên đã hoàn thành tốt 2/3 câu hỏi, tuy nhiên vẫn cần cải thiện kiến thức về useEffect.','2026-06-02 19:43:38','SUBMITTED',1),('078e8b9a-49dc-41f2-8139-2b112417e821',6,'6b54c110-f8c9-4051-994c-c45629db02f5','{\"code\":null,\"answers\":{\"0\":\"A\"}}',100,'Học viên đã trả lời đúng cả câu hỏi','2026-05-26 02:03:41','PASSED',2),('08715232-d292-40ec-ac19-61a028560cf8',22,'6b54c110-f8c9-4051-994c-c45629db02f5','{\"code\":\"public class Solution {\\n    public static long factorial(int n) {\\n        // Viết code của bạn ở đây\\n        return 0;\\n    }\\n}\",\"answers\":null}',0,'Code bị lỗi biên dịch: Không thể kết nối tới Piston. Vui lòng thử lại.','2026-06-03 08:04:05','SUBMITTED',2),('0a312f50-82be-44cd-ada9-70b483a1b817',6,'b645fee7-81d2-4d42-9b88-672f1aa828e8','{\"code\":null,\"answers\":{\"0\":\"B\"}}',0,'Cần nâng cao hơn','2026-05-27 21:37:15','SUBMITTED',2),('11a0c2b6-25ba-4818-8f2d-81c2301eea7b',10,'fe0dba25-de24-4f4b-9e66-48a46eba5e1a','{\"code\":null,\"answers\":{\"0\":\"D\",\"1\":\"B\",\"2\":\"B\"}}',33,'Học viên cần cải thiện kiến thức về ngôn ngữ C++ và các thư viện của nó','2026-05-31 09:41:02','SUBMITTED',10),('1796f1de-c542-4bb6-a1cd-e555c7bbf76c',10,'fe0dba25-de24-4f4b-9e66-48a46eba5e1a','{\"code\":null,\"answers\":{\"0\":\"A\",\"1\":\"D\",\"2\":\"B\"}}',33,'Học viên cần cải thiện kiến thức nền tảng về C++','2026-06-04 00:39:04','SUBMITTED',13),('1930cea8-e3be-45f6-9c23-311670b3a0d9',10,'b645fee7-81d2-4d42-9b88-672f1aa828e8','{\"code\":null,\"answers\":{\"0\":\"D\",\"1\":\"C\",\"2\":\"B\"}}',67,'Học viên đã làm tốt 2/3 câu hỏi, cần cải thiện kiến thức về loại ngôn ngữ của C++','2026-05-31 02:12:32','SUBMITTED',1),('2cd8e988-63b2-4647-8d5e-233ac0d1f496',7,'6b54c110-f8c9-4051-994c-c45629db02f5','{\"code\":\"public class Main {\\n    public static int sumArray(int[] arr) {\\n        // Viết code của bạn ở đây\\n        \\n    }\\n\\n    public static void main(String[] args) {\\n        System.out.println(sumArray(new int[]{1, 2, 3, 4, 5})); // 15\\n        System.out.println(sumArray(new int[]{}));               // 0\\n        System.out.println(sumArray(new int[]{-1, -2, 3}));      // 0\\n    }\\n}\",\"answers\":null}',0,'Hàm của bạn chưa được hoàn thiện. Hãy thử lại, tính tổng các phần tử trong mảng bằng cách sử dụng vòng lặp hoặc công thức tính tổng.','2026-05-25 08:41:46','SUBMITTED',4),('2d16226f-62f7-4032-ade3-b3c194b81b9f',11,'fe0dba25-de24-4f4b-9e66-48a46eba5e1a','{\"code\":\"#include <iostream>\\nusing namespace std;\\n\\nint main() {\\n    cout<<\\\"xin chao\\\"\\n    \\n    return 0;\\n}\",\"answers\":null}',0,'Code bị lỗi biên dịch: main.cpp: In function \'int main()\':\nmain.cpp:5:21: error: expected \';\' before \'return\'\n    5 |     cout<<\"xin chao\"\n      |                     ^\n      |                     ;\n    6 | \n    7 |     return 0;\n      |     ~~~~~~           \nchmod: cannot access \'a.out\': No such file or directory\n','2026-06-04 01:10:45','SUBMITTED',2),('30d27f74-0f50-48de-bb1b-01bc9ee3a258',6,'b645fee7-81d2-4d42-9b88-672f1aa828e8','{\"code\":null,\"answers\":{\"0\":\"A\"}}',100,'Học viên đã hoàn thành xuất sắc bài trắc nghiệm này, chúc mừng!','2026-05-27 21:36:59','PASSED',1),('3142eb2b-517e-4b19-8302-42cadbbcb996',19,'5bceec4e-e366-48ea-a7ef-833f0f58950d','{\"code\":\"def sum_list(nums):\\n    return sum(nums)\",\"answers\":null}',100,NULL,'2026-06-01 20:14:02','PASSED',1),('32000d6a-20cd-41f2-948a-fb647af25085',3,'7f5d3356-4226-495a-8d12-4aef4764df29','{\"code\":null,\"answers\":{\"0\":\"D\",\"1\":\"D\"}}',0,'Bạn cần cố gắng hơn để đạt được kết quả tốt hơn. Hãy xem lại các câu hỏi và giải thích để hiểu rõ hơn.','2026-05-26 02:49:51','SUBMITTED',5),('351a6bcb-3ed5-48e5-ab2e-ba8b22f9ad65',11,'fe0dba25-de24-4f4b-9e66-48a46eba5e1a','{\"code\":\"#include <iostream>\\nu